  }
  const contextSize = JSON.stringify(snapshot.files).length;
  if (contextSize > 200000) throw new Error('Source context exceeds 200 KB. Select a smaller project directory with its tests/docs. Dependency lockfiles are retained but excluded from model context.');
  // Documentation in the submitted snapshot supplies lightweight project evidence.
  const documents = Object.entries(snapshot.files).filter(([file]) => /\.(md|txt)$/.test(file)).map(([file, text]) => ({ id: file, text }));
  const index = new MiniSearch({ fields: ['text'], storeFields: ['text'] });
  index.addAll(documents);
  const query = report.rules.map((rule) => rule.text).join(' ');
  const retrievedDocuments = variant === 'B0' ? [] : index.search(query, { combineWith: 'OR', prefix: true }).slice(0, 4).map((item) => ({ file: String(item.id), text: String(item.text), score: item.score, sha256: createHash('sha256').update(String(item.text)).digest('hex') }));
  report.retrieval = { query, documents: retrievedDocuments };
  const context = { runtime: report.runtime || "python", artifactDirectory: "reqtest_generated", services: report.projectSetup?.services || [], installed: report.projectSetup?.installed || [], testFormat: report.runtime === "node" ? "Use node:test and node:assert/strict. Each file is saved at reqtest_generated/test_reqtest_<id>.test.ts. Resolve relative imports from that directory: a root shipping.mjs module is imported as ../shipping.mjs; a root shipping.ts module as ../shipping.ts. Each artifact must import test from node:test, declare one named function test_..., and register it with test(\"test_function_name\", test_function_name). Register exactly one top-level test case; do not use describe or nested suites. Use TypeScript-compatible imports. Local service URLs may be read from DATABASE_URL or REDIS_URL only when explicitly needed by the requirement." : "Use pytest. Each artifact declares one def test_... function. Only explicitly supplied services may use DATABASE_URL or REDIS_URL from the environment.", rules: report.rules, requirementContext: report.requirementInput?.context || '', files: variant === 'B0' ? Object.fromEntries(Object.entries(snapshot.files).filter(([file]) => sourceFile(file))) : snapshot.files, functions: snapshot.functions, existingTests: variant === 'B0' ? [] : snapshot.nodes, collection: ['B0', 'B1'].includes(variant) ? undefined : snapshot.collection, retrievedDocuments: retrievedDocuments.map(document => ({ file: document.file, score: document.score, sha256: document.sha256 })) };
  report.analysis = ['B0', 'B1'].includes(variant) ? { behaviors: report.rules.map((rule, index) => ({ id: 'B' + (index + 1), ruleId: rule.id, quote: rule.text, text: rule.text, category: 'rule', issue: 'none', reason: 'Baseline ID scaffolding; no semantic decomposition.', files: [], existingTests: [], evidence: [], gaps: ['Requirement not yet checked.'] })), inconsistencies: [] } : await stage('Analyze requirements and consistency', () => ask(analysisSchema, 'Decompose EACH requirement into atomic rules, boundaries, conditions and exceptions. Original document IDs are retained as originalId; use internal R IDs in output links. requirementContext is supporting document text, not additional independently verified requirements; do not invent contract clauses from it. Record incomplete analysis honestly when output limits prevent full decomposition. Each B ID is unique. Categorize ambiguous/incomplete/not_testable requirements. List independently checkable finite witness gaps (for example the exact threshold, immediately below it, an interior value, or an exception). Never label one gap as exhaustive verification of an entire range or combine unrelated type/value/exception obligations in one gap. Write gaps as plain descriptions without numbering; a gap\'s zero-based position in the list is its index. Map existing collected test IDs only when their assertions check that behavior; cite code and test quotes. Report cross-artifact inconsistencies as potential conflicts without assuming which artifact is correct. Each inconsistency MUST include behaviorIds referencing the affected B IDs from that same requirement. Copy source/test/document evidence as a single verbatim line from the named file; never paraphrase it or replace real line breaks with literal backslash escapes. Preserve unknowns.', context, report.model, signal));
  const original = structuredClone(report.analysis);
  try { validateAnalysis(report.analysis, report, snapshot); }
  catch (error) {
    const message = error instanceof Error ? error.message : 'Invalid analysis evidence.';
    report.analysisCorrection = { original, error: message };
    const invalidEvidence = [...original.behaviors, ...original.inconsistencies].flatMap(item => item.evidence).filter(item => !validEvidence([item], snapshot));
    report.analysis = await stage('Correct invalid analysis evidence', () => ask(analysisSchema, 'Correct the supplied analysis once using ONLY the original requirements and files. Fix invalid IDs or citations identified by validationError and invalidEvidence. Every evidence quote must be a single unchanged source line from its exact file key, not a paraphrase or backslash-escaped multiline excerpt. Preserve justified findings; remove a claim only if original evidence cannot support it. Requirement quotes remain exact original rule text. Invent no new contract or evidence. The result will undergo the same strict validation again.', { ...context, previousAnalysis: original, validationError: message, invalidEvidence }, report.model, signal));
    validateAnalysis(report.analysis, report, snapshot);
  }
  report.baseline = await stage('Measure existing tests', () => measureProject(root, snapshot.nodes.length ? snapshot.nodes : [1, 2, 3, 4].includes(snapshot.collection.exitCode) ? ['.'] : [], false, signal, image));
