    quote, files: z.array(z.enum(Object.keys(files).filter(sourceFile))).max(4),
    existingTests: z.array(nodes.length ? z.enum(nodes) : z.string()).max(nodes.length ? 8 : 0),
    evidence: z.array(evidence).max(8),
  });
